 * （ユーザー入力だけでなく、アシストパネルからの訳文反映でも追従させるため）。
 */
function AutoGrowTextarea({
  disabled,
  onChange,
  onClick,
  onFocus,
  value,
}: {
  disabled: boolean;
  onChange: (value: string) => void;
  onClick: (event: React.MouseEvent<HTMLTextAreaElement>) => void;
  onFocus: () => void;
  value: string;
}): React.JSX.Element {
  const ref = useRef<HTMLTextAreaElement>(null);

  useLayoutEffect(() => {
    const element = ref.current;
    if (!element) {
      return;
    }
    // いったん高さをリセットしてから内容の高さに合わせる（縮小にも追従させる）
    element.style.height = "auto";
    element.style.height = `${element.scrollHeight}px`;
  }, [value]);

  return (
    <textarea
      className="min-h-9 w-full resize-none overflow-hidden bg-transparent px-1.5 py-1 text-sm/relaxed outline-none"
      disabled={disabled}
      onChange={(event) => onChange(event.target.value)}
      onClick={onClick}
      onFocus={onFocus}
      ref={ref}
      rows={1}
      value={value}
    />
  );
}

